import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, output, Output, SimpleChanges } from '@angular/core';
import { AvatarComponent } from '../../avatar/avatar.component';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { selectedContactList } from '../../../interfaces/issue.interface';
import { CommonModule } from '@angular/common';
import { MatDialog } from '@angular/material/dialog';
import { ContactFormComponent } from '../contact-form/contact-form.component';
import { I } from '@angular/cdk/keycodes';
import { ContactService } from '../../../services/contact/contact.service';
import { ContactdetailComponent } from '../contactdetail/contactdetail.component';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';

@Component({
  selector: 'selected-contact',
  standalone: true,
  // changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [AvatarComponent, ButtonComponent, IconComponent, MatTooltipModule, CommonModule],
  templateUrl: './selected-contact.component.html',
  styleUrl: './selected-contact.component.scss'
})
export class SelectedContactComponent {
  @Input() deletebtn: boolean = false;
  @Input() showinfo: boolean = false;
  @Input() largeView: boolean = false;
  @Input() selectedContacts: selectedContactList[];
  @Input() canDelete: boolean = false;
  @Input() hasshadow: boolean = false;
  @Input() canEdit: boolean = false;
  @Input() nCaseid: string;
  @Input() ismyfiles: boolean = false;
  @Input() hasBackdrop: boolean = false;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  dialogRef: any;
  constructor(private cdr: ChangeDetectorRef, private dialog: MatDialog, private CService: ContactService) { }


  deleteContact(x, index: number) {
    this.selectedContacts.splice(index, 1);
    this.OnEvent.emit({ event: 'DELETE', data: { nContactid: x.nContactid } });
  }


  ngOnChanges(changes: SimpleChanges): void {
    if (changes["selectedContacts"]) {
      this.cdr.detectChanges();
    }
  }

  edit(x) {
    this.OnEvent.emit({ event: 'EDIT', data: { nContactid: x.nContactid } });
  }


  async editContact(x) {
    if (this.dialogRef) return;
    let edit_detail = await this.CService.getContactDetail(x.nContactid);
    this.dialogRef = this.dialog.open(ContactFormComponent, {
      width: !this.ismyfiles ? '440px' : '436px',
      height: !this.ismyfiles ? 'calc(100vh - 56px)' : 'calc(100% - 220px)',
      position: !this.ismyfiles ? { right: '0vh', top: '56px' } : { right: '24px', top: '200px' },
      hasBackdrop: this.hasBackdrop ? this.hasBackdrop : false,
      panelClass: this.hasBackdrop ? 'noroundedandshadow' : 'noshadow'
      // data: {nCaseid:this.nCaseid}
    });
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    this.dialogRef.componentInstance.editable_list = edit_detail
    this.dialogRef.afterClosed().subscribe(result => {
      this.dialogRef = null;
      if (result) {
        this.OnEvent.emit({ event: 'RELOAD', data: { nContactid: x.nContactid } });
        // this.isLoading = true;
        // this.ngOnInit();
      }
    });
  }


  async contactDetail(x) {
    
    if (this.dialogRef) return;
    let edit_detail;
    edit_detail = await this.CService.getContactDetail(x.nContactid);
    this.dialogRef = this.dialog.open(ContactdetailComponent, {
      width: !this.ismyfiles ? '440px' : '436px',
      height: !this.ismyfiles ? 'calc(100vh - 56px)' : 'calc(100% - 220px)',
      position: !this.ismyfiles ? { right: '0vh', top: '56px' } : { right: '24px', top: '200px' },
      hasBackdrop: this.hasBackdrop ? this.hasBackdrop : false,
      panelClass: this.hasBackdrop ? 'noroundedandshadow' : 'noshadow'
      // data: {nCaseid:this.nCaseid}
    });
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    this.dialogRef.componentInstance.detail = edit_detail;
    this.dialogRef.afterClosed().subscribe(result => {
      this.dialogRef = null;
      if (result) {
        result == 'EDIT' ? this.editContact(x) : '';
      }
    });
  }




}
